mapper.select:
select ug.id, ug.user_id, ug.group_id, g.group_name, g.group_code, u.user_code, u.user_name, ug.relative_generation_diff, ug.kinship_level from mes_msg_user_group ug inner join mes_msg_user u on ug.user_id = u.id and u.deleted_flag = '0' inner join mes_msg_group g on ug.group_id = g.id and g.deleted_flag = '0'
ug.deleted_flag = '0'
and ug.id = #{param.id}
and ug.user_id = #{param.userId}
and ug.group_id = #{param.groupId}
and (g.group_name like concat('%', #{param.groupName}, '%') or g.group_code like concat('%', #{param.groupName}, '%'))
and (u.user_name like concat('%', #{param.userName}, '%') or u.user_code like concat('%', #{param.userName}, '%'))
order by ug.update_time desc
